/** Drop visuals that cannot be rendered safely rather than failing the whole deck. */
async function sanitizeSlides(courseId: string, slides: Slide[]): Promise<Slide[]> {
  const noVisual = { kind: "none" as const, figureId: "", svg: "", caption: "" };
  const cleaned: Slide[] = [];
  for (const slide of slides) {
    const { visual } = slide;
    if (visual.kind === "textbook_figure" && !(await findFigure(courseId, visual.figureId))) {
      cleaned.push({ ...slide, visual: noVisual });
      continue;
    }
    if (visual.kind === "diagram") {
      const svg = visual.svg.trim();
      const isUnsafe = /<script|<foreignObject|\son\w+\s*=|href\s*=\s*["'](?!#)/i.test(svg);
      if (!svg.startsWith("<svg") || !svg.endsWith("</svg>") || isUnsafe) {
        cleaned.push({ ...slide, visual: noVisual });
        continue;
      }
    }
    cleaned.push(slide);
  }
  return cleaned;
}
